'use client';

/**
 * Live waitlist intelligence dashboard (client side of /admin).
 *
 * Polls /api/admin/waitlist every 30s (paused while the tab is hidden),
 * renders stat cards, a 48h signup trend, source breakdown, the companies
 * panel (team clusters + known orgs first), and a live feed / messages view.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import type { WaitlistIntel, IntelCompany, IntelRecent } from '@/lib/admin/waitlist-intel';

const POLL_MS = 30_000;

// --- time helpers -----------------------------------------------------------

function ago(iso: string): string {
  const s = (Date.now() - new Date(iso).getTime()) / 1000;
  if (s < 60) return `${Math.max(0, Math.floor(s))}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

function stamp(iso: string): string {
  return new Date(iso).toLocaleString(undefined, {
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

function hourLabel(iso: string): string {
  return new Date(iso).toLocaleString(undefined, {
    weekday: 'short',
    hour: 'numeric',
  });
}

// --- subcomponents -----------------------------------------------------------

function StatCard({ label, value, accent }: { label: string; value: string | number; accent?: boolean }) {
  return (
    <div className={`aw-stat${accent ? ' aw-stat-accent' : ''}`}>
      <div className="aw-stat-value">{value}</div>
      <div className="aw-stat-label">{label}</div>
    </div>
  );
}

function TrendChart({ trend }: { trend: WaitlistIntel['trend'] }) {
  const max = Math.max(1, ...trend.map((t) => t.count));
  const total = trend.reduce((n, t) => n + t.count, 0);
  return (
    <div
      className="aw-trend"
      role="img"
      aria-label={`Signups per hour, last 48 hours: ${total} total, busiest hour ${max}`}
    >
      {trend.map((t) => (
        <div
          key={t.hourStart}
          className="aw-trend-bar"
          title={`${hourLabel(t.hourStart)} — ${t.count} signup${t.count === 1 ? '' : 's'}`}
        >
          <div
            className="aw-trend-fill"
            style={{ height: `${Math.max(t.count > 0 ? 6 : 0, (t.count / max) * 100)}%` }}
          />
        </div>
      ))}
    </div>
  );
}

function SourceBars({ sources }: { sources: WaitlistIntel['sources'] }) {
  const max = Math.max(1, ...sources.map((s) => s.count));
  return (
    <div className="aw-sources">
      {sources.map((s) => (
        <div key={s.source} className="aw-source-row" title={`${s.count} total · ${s.last24h} in last 24h`}>
          <span className="aw-source-name">{s.source}</span>
          <span className="aw-source-track">
            <span className="aw-source-fill" style={{ width: `${(s.count / max) * 100}%` }} />
          </span>
          <span className="aw-source-count">
            {s.count}
            {s.last24h > 0 && <em className="aw-source-delta">+{s.last24h}</em>}
          </span>
        </div>
      ))}
    </div>
  );
}

function CompanyCard({ company }: { company: IntelCompany }) {
  return (
    <details className="aw-company" open={company.count >= 3}>
      <summary className="aw-company-summary">
        <span className="aw-company-domain">{company.domain}</span>
        {company.count > 1 && <span className="aw-badge aw-badge-cluster">×{company.count}</span>}
        {company.knownName && <span className="aw-badge aw-badge-known">{company.knownName}</span>}
        {company.kind === 'edu' && <span className="aw-badge aw-badge-edu">edu</span>}
        <span className="aw-company-when">{ago(company.latestAt)}</span>
      </summary>
      <div className="aw-company-entries">
        {company.entries.map((e) => (
          <div key={e.email} className="aw-entry">
            <div className="aw-entry-head">
              <span className="aw-entry-email">{e.email}</span>
              <span className="aw-chip">{e.source ?? '?'}</span>
              <span className="aw-entry-when" title={stamp(e.createdAt)}>{ago(e.createdAt)}</span>
            </div>
            {e.note && <div className="aw-note">“{e.note}”</div>}
          </div>
        ))}
      </div>
    </details>
  );
}

function FeedRow({ row }: { row: IntelRecent }) {
  return (
    <div className={`aw-feed-row aw-feed-${row.domainKind}`}>
      <div className="aw-entry-head">
        <span className="aw-entry-email">{row.email}</span>
        {row.knownName && <span className="aw-badge aw-badge-known">{row.knownName}</span>}
        {row.domainKind === 'corporate' && !row.knownName && <span className="aw-badge aw-badge-corp">corp</span>}
        {row.domainKind === 'edu' && <span className="aw-badge aw-badge-edu">edu</span>}
        <span className="aw-chip">{row.source ?? '?'}</span>
        <span className="aw-entry-when" title={stamp(row.createdAt)}>{ago(row.createdAt)}</span>
      </div>
      {row.note && <div className="aw-note">“{row.note}”</div>}
    </div>
  );
}

// --- main component ----------------------------------------------------------

export default function AdminWaitlist({ embedded = false }: { embedded?: boolean }) {
  const [data, setData] = useState<WaitlistIntel | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [lastFetched, setLastFetched] = useState<number | null>(null);
  const [tab, setTab] = useState<'feed' | 'messages'>('feed');
  const [baseline, setBaseline] = useState<number | null>(null);
  // Monotonic request id: only the newest in-flight fetch may commit state,
  // so an older slow response can't overwrite a newer fast one.
  const reqSeq = useRef(0);

  const load = useCallback(async () => {
    const seq = ++reqSeq.current;
    try {
      const res = await fetch('/api/admin/waitlist', { cache: 'no-store' });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const intel: WaitlistIntel = await res.json();
      if (seq !== reqSeq.current) return; // stale response — drop it
      setData(intel);
      setError(null);
      setLastFetched(Date.now());
      setBaseline((b) => b ?? intel.totals.all);
    } catch (e) {
      if (seq !== reqSeq.current) return;
      setError(e instanceof Error ? e.message : 'fetch failed');
    }
  }, []);

  useEffect(() => {
    void load();
    const interval = setInterval(() => {
      if (document.visibilityState === 'visible') void load();
    }, POLL_MS);
    const onVisible = () => {
      if (document.visibilityState === 'visible') void load();
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      clearInterval(interval);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [load]);

  if (!data) {
    return (
      <div className={`aw-shell${embedded ? ' aw-shell-embedded' : ''}`}>
        <div className="aw-loading">{error ? `Failed to load: ${error}` : 'Loading waitlist…'}</div>
      </div>
    );
  }

  const { totals, trend, sources, companies, recent, notes } = data;
  const delta = baseline !== null ? totals.all - baseline : 0;
  const clusters = companies.filter((c) => c.count >= 2);

  return (
    <div className={`aw-shell${embedded ? ' aw-shell-embedded' : ''}`}>
      <header className="aw-header">
        <div className="aw-title-block">
          <h1 className="aw-title">
            <span className="aw-live-dot" aria-hidden />
            Waitlist
          </h1>
          <span className="aw-subtitle">
            {error
              ? `refresh failed (${error}) — showing last good data`
              : lastFetched
                ? `updated ${new Date(lastFetched).toLocaleTimeString()} · polls every 30s`
                : ''}
            {delta > 0 && <strong className="aw-delta"> +{delta} since you opened</strong>}
          </span>
        </div>
        <button className="aw-refresh" onClick={() => void load()}>
          Refresh
        </button>
      </header>

      <section className="aw-stats">
        <StatCard label="Total signups" value={totals.all} accent />
        <StatCard label="Last hour" value={totals.lastHour} />
        <StatCard label="Last 24h" value={totals.last24h} />
        <StatCard label="Last 7d" value={totals.last7d} />
        <StatCard label="Messages" value={totals.withNotes} />
        <StatCard label="Corporate" value={`${totals.corporatePct}%`} />
      </section>

      <section className="aw-panel">
        <h2 className="aw-panel-title">Signups per hour — last 48h</h2>
        <TrendChart trend={trend} />
      </section>

      <div className="aw-columns">
        <div className="aw-col">
          <section className="aw-panel">
            <h2 className="aw-panel-title">
              Companies <span className="aw-panel-meta">{companies.length} domains · {clusters.length} team clusters</span>
            </h2>
            <div className="aw-company-list">
              {companies.map((c) => (
                <CompanyCard key={c.domain} company={c} />
              ))}
              {companies.length === 0 && <div className="aw-empty">No corporate domains yet.</div>}
            </div>
          </section>

          <section className="aw-panel">
            <h2 className="aw-panel-title">Sources</h2>
            <SourceBars sources={sources} />
          </section>
        </div>

        <div className="aw-col">
          <section className="aw-panel">
            <div className="aw-tabs">
              <button
                className={`aw-tab${tab === 'feed' ? ' aw-tab-active' : ''}`}
                aria-pressed={tab === 'feed'}
                onClick={() => setTab('feed')}
              >
                Live feed
              </button>
              <button
                className={`aw-tab${tab === 'messages' ? ' aw-tab-active' : ''}`}
                aria-pressed={tab === 'messages'}
                onClick={() => setTab('messages')}
              >
                Messages <span className="aw-tab-count">{notes.length}</span>
              </button>
            </div>

            {tab === 'feed' ? (
              <div className="aw-feed">
                {recent.map((r) => (
                  <FeedRow key={r.id} row={r} />
                ))}
              </div>
            ) : (
              <div className="aw-feed">
                {notes.map((n) => (
                  <div key={`${n.email}-${n.createdAt}`} className="aw-feed-row">
                    <div className="aw-entry-head">
                      <span className="aw-entry-email">{n.email}</span>
                      {n.knownName && <span className="aw-badge aw-badge-known">{n.knownName}</span>}
                      <span className="aw-chip">{n.source ?? '?'}</span>
                      <span className="aw-entry-when" title={stamp(n.createdAt)}>{ago(n.createdAt)}</span>
                    </div>
                    <div className="aw-note">“{n.note}”</div>
                  </div>
                ))}
                {notes.length === 0 && <div className="aw-empty">No messages yet.</div>}
              </div>
            )}
          </section>
        </div>
      </div>
    </div>
  );
}

/**
 * /admin — owner-only waitlist intelligence dashboard.
 *
 * Server component gate: middleware already bounces unauthenticated users to
 * /login; here we additionally 404 any authenticated non-admin (allowlist in
 * lib/admin/auth). The client component does the live rendering.
 */

import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { getUser } from '@/lib/auth-server';
import { isAdminUser } from '@/lib/admin/auth';
import AdminDashboard from './AdminDashboard';
import './admin.css';

export const dynamic = 'force-dynamic';

export const metadata: Metadata = {
  title: 'Waitlist — admin',
  robots: { index: false, follow: false },
};

export default async function AdminPage() {
  const user = await getUser();

  if (!isAdminUser(user)) notFound();

  return <AdminDashboard />;
}

'use client';

import { useState } from 'react';
import AdminWaitlist from './AdminWaitlist';
import NoteMirrorHealth from './NoteMirrorHealth';
import TurbopufferCosts from './TurbopufferCosts';
import BillingHealth from './BillingHealth';
import TpufRepairHealth from './TpufRepairHealth';
import ActivationHealth from './ActivationHealth';

type Surface = 'waitlist' | 'activation' | 'turbopuffer' | 'repair' | 'notes' | 'billing';

export default function AdminDashboard() {
  const [surface, setSurface] = useState<Surface>('waitlist');
  return (
    <div className="aw-shell">
      <nav className="aw-admin-nav" aria-label="Admin sections">
        <button
          className={`aw-admin-nav-btn${surface === 'waitlist' ? ' is-active' : ''}`}
          aria-pressed={surface === 'waitlist'}
          onClick={() => setSurface('waitlist')}
        >
          Waitlist
        </button>
        <button
          className={`aw-admin-nav-btn${surface === 'activation' ? ' is-active' : ''}`}
          aria-pressed={surface === 'activation'}
          onClick={() => setSurface('activation')}
        >
          Activation
        </button>
        <button
          className={`aw-admin-nav-btn${surface === 'turbopuffer' ? ' is-active' : ''}`}
          aria-pressed={surface === 'turbopuffer'}
          onClick={() => setSurface('turbopuffer')}
        >
          Turbopuffer cost
        </button>
        <button
          className={`aw-admin-nav-btn${surface === 'repair' ? ' is-active' : ''}`}
          aria-pressed={surface === 'repair'}
          onClick={() => setSurface('repair')}
        >
          Mirror repair
        </button>
        <button
          className={`aw-admin-nav-btn${surface === 'notes' ? ' is-active' : ''}`}
          aria-pressed={surface === 'notes'}
          onClick={() => setSurface('notes')}
        >
          Note mirror
        </button>
        <button
          className={`aw-admin-nav-btn${surface === 'billing' ? ' is-active' : ''}`}
          aria-pressed={surface === 'billing'}
          onClick={() => setSurface('billing')}
        >
          Billing health
        </button>
      </nav>
      {surface === 'waitlist' ? (
        <AdminWaitlist embedded />
      ) : surface === 'activation' ? (
        <ActivationHealth />
      ) : surface === 'turbopuffer' ? (
        <TurbopufferCosts />
      ) : surface === 'repair' ? (
        <TpufRepairHealth />
      ) : surface === 'notes' ? (
        <NoteMirrorHealth />
      ) : (
        <BillingHealth />
      )}
    </div>
  );
}

/**
 * Waitlist intelligence builder
 *
 * Pure aggregation over email_waitlist rows → one JSON payload the admin
 * dashboard renders. No DB access here so the logic is unit-testable; the
 * API route fetches rows and calls buildWaitlistIntel().
 *
 * Classification: every signup's email domain is bucketed as
 *   personal  — free/consumer providers (gmail, qq, outlook…) + known typos
 *   edu       — academic domains (.edu, .edu.xx, .ac.xx)
 *   corporate — everything else (company or custom domains)
 * Corporate domains with 2+ signups are "team clusters" — the strongest
 * adoption signal we have. KNOWN_COMPANIES adds display names for orgs
 * we've manually identified.
 */

export interface WaitlistRow {
  id: number;
  email: string;
  source: string | null;
  note: string | null;
  createdAt: Date;
}

export type DomainKind = 'corporate' | 'edu' | 'personal';

export interface IntelEntry {
  email: string;
  source: string | null;
  note: string | null;
  createdAt: string;
}

export interface IntelCompany {
  domain: string;
  kind: 'corporate' | 'edu';
  count: number;
  knownName: string | null;
  latestAt: string;
  entries: IntelEntry[];
}

export interface IntelRecent extends IntelEntry {
  id: number;
  domainKind: DomainKind;
  knownName: string | null;
}

export interface WaitlistIntel {
  generatedAt: string;
  totals: {
    all: number;
    lastHour: number;
    last24h: number;
    last7d: number;
    withNotes: number;
    corporate: number;
    corporatePct: number;
  };
  trend: Array<{ hourStart: string; count: number }>;
  sources: Array<{ source: string; count: number; last24h: number }>;
  companies: IntelCompany[];
  recent: IntelRecent[];
  notes: Array<IntelEntry & { knownName: string | null }>;
}

/** Free/consumer email providers — never companies. */
const FREE_PROVIDERS = new Set([
  // Big global
  'gmail.com', 'googlemail.com', 'icloud.com', 'me.com', 'mac.com',
  'outlook.com', 'outlook.es', 'outlook.it', 'outlook.fr', 'outlook.de',
  'outlook.com.br', 'outlook.in', 'hotmail.com', 'hotmail.co.uk',
  'hotmail.fr', 'hotmail.de', 'hotmail.es', 'hotmail.it', 'live.com',
  'live.cn', 'live.co.uk', 'msn.com', 'yahoo.com', 'yahoo.co.uk',
  'yahoo.fr', 'yahoo.de', 'yahoo.es', 'yahoo.it', 'yahoo.com.br',
  'yahoo.co.in', 'yahoo.com.tw', 'ymail.com', 'rocketmail.com', 'aol.com',
  // Privacy / indie
  'proton.me', 'protonmail.com', 'pm.me', 'tutanota.com', 'tuta.io',
  'fastmail.com', 'hey.com', 'duck.com', 'duckduckgo.com', 'hushmail.com',
  'passmail.net', 'altmail.kr', 'mail.com', 'dr.com', 'gmx.com', 'gmx.de',
  'gmx.net', 'gmx.at', 'gmx.ch', 'zoho.com', 'zohomail.com',
  // China
  'qq.com', '163.com', '126.com', '139.com', 'foxmail.com', 'sina.com',
  'sina.cn', 'sohu.com', 'aliyun.com', 'yeah.net', '189.cn', '21cn.com',
  // Korea / Japan
  'naver.com', 'daum.net', 'hanmail.net', 'kakao.com', 'yahoo.co.jp',
  // Russia / Eastern Europe
  'mail.ru', 'yandex.ru', 'yandex.com', 'bk.ru', 'inbox.ru', 'list.ru',
  'rambler.ru', 'ukr.net', 'i.ua', 'tut.by', 'seznam.cz', 'wp.pl',
  'o2.pl', 'interia.pl', 'op.pl', 'abv.bg',
  // Telco / ISP
  'sbcglobal.net', 'att.net', 'verizon.net', 'comcast.net', 'cox.net',
  'charter.net', 'earthlink.net', 'bellsouth.net', 'shaw.ca', 'rogers.com',
  'sympatico.ca', 'btinternet.com', 'sky.com', 'talktalk.net',
  'virginmedia.com', 'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr',
  'laposte.net', 'libero.it', 'tiscali.it', 'telenet.be', 'ziggo.nl',
  'xs4all.nl', 't-online.de', 'web.de', 'freenet.de', 'arcor.de',
  'bluewin.ch', 'telia.com', 'mail.dk',
  // Test / placeholder
  'example.com',
]);

/** Obvious typo'd free providers — a person, not an org. */
const TYPO_PROVIDERS = new Set([
  'gamil.com', 'gmial.com', 'gmal.com', 'gnail.com', 'gmaill.com',
  'gmnail.com', 'gmail.co', 'gmail.cm', 'gmail.con', 'gmail..com',
  'göail.com', 'gemail.com', 'gimail.com', 'hotmial.com', 'hotnail.com',
  'hotmal.com', 'outlok.com', 'outloook.com', 'yaho.com', 'yahooo.com',
  'iclod.com', 'icoud.com', 'icloud.con', '63.com', 'gamill.com',
]);

/**
 * Orgs we've manually identified (domain → display name). Not exhaustive —
 * unknown corporate domains still surface, just without a friendly name.
 */
const KNOWN_COMPANIES: Record<string, string> = {
  'airbnb.com': 'Airbnb',
  'accenture.com': 'Accenture',
  'tencent.com': 'Tencent',
  'zillowgroup.com': 'Zillow Group',
  'checkpoint.com': 'Check Point',
  'digitalocean.com': 'DigitalOcean',
  'thetradedesk.com': 'The Trade Desk',
  'pony.ai': 'Pony.ai',
  'lixiang.com': 'Li Auto',
  'lotuscars.com.cn': 'Lotus Cars',
  'talkdesk.com': 'Talkdesk',
  'deputy.com': 'Deputy',
  'groww.in': 'Groww',
  'grofers.com': 'Blinkit (Grofers)',
  'zomato.com': 'Zomato',
  'fandango.com': 'Fandango',
  'exclusive-networks.com': 'Exclusive Networks',
  'ventionteams.com': 'Vention',
  'webpros.com': 'WebPros (cPanel/Plesk)',
  'simformsolutions.com': 'Simform',
  'nextlabs.com': 'NextLabs',
  'novibet.com': 'Novibet',
  'truecommerce.com': 'TrueCommerce',
  'myalfred.com': 'myAlfred (UAE super-app)',
  'chilipiper.com': 'Chili Piper',
  'aldar.com': 'Aldar Properties',
  'buk.cl': 'Buk',
  'aunalytics.com': 'Aunalytics',
  '3yourmind.com': '3YOURMIND',
  'kickdrumtech.com': 'Kickdrum',
  'dhc.com.cn': 'DHC Software',
  'wejungle.com': 'Jungle',
};

/** Academic domains: .edu, or .edu.xx / .ac.xx ccTLD second-levels. */
const EDU_RE = /\.edu$|\.(edu|ac)\.[a-z]{2}$/;

export function classifyDomain(domain: string): DomainKind {
  if (!domain) return 'personal'; // malformed email — a person, not an org
  if (FREE_PROVIDERS.has(domain) || TYPO_PROVIDERS.has(domain)) return 'personal';
  if (EDU_RE.test(domain)) return 'edu';
  return 'corporate';
}

const HOUR_MS = 3_600_000;
const DAY_MS = 86_400_000;
const TREND_HOURS = 48;
const RECENT_LIMIT = 100;

export function buildWaitlistIntel(rows: WaitlistRow[]): WaitlistIntel {
  const now = Date.now();

  // Drop placeholder/test rows entirely.
  const real = rows.filter((r) => !r.email.toLowerCase().endsWith('@example.com'));
  // Newest first everywhere.
  real.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());

  const domainOf = (email: string) => (email.split('@')[1] ?? '').toLowerCase().trim();
  const hasNote = (r: WaitlistRow) => Boolean(r.note && r.note.trim());

  // --- Totals -------------------------------------------------------------
  const inWindow = (ms: number) => real.filter((r) => now - r.createdAt.getTime() < ms).length;
  let corporateCount = 0;
  for (const r of real) {
    if (classifyDomain(domainOf(r.email)) === 'corporate') corporateCount += 1;
  }

  // --- Hourly trend (last 48h, aligned to hour starts) ---------------------
  const trendStart = Math.floor(now / HOUR_MS) * HOUR_MS - (TREND_HOURS - 1) * HOUR_MS;
  const buckets = new Array<number>(TREND_HOURS).fill(0);
  for (const r of real) {
    const idx = Math.floor((r.createdAt.getTime() - trendStart) / HOUR_MS);
    if (idx >= 0 && idx < TREND_HOURS) buckets[idx] += 1;
  }
  const trend = buckets.map((count, i) => ({
    hourStart: new Date(trendStart + i * HOUR_MS).toISOString(),
    count,
  }));

  // --- Sources --------------------------------------------------------------
  const sourceMap = new Map<string, { count: number; last24h: number }>();
  for (const r of real) {
    const key = r.source?.trim() || '(none)';
    const s = sourceMap.get(key) ?? { count: 0, last24h: 0 };
    s.count += 1;
    if (now - r.createdAt.getTime() < DAY_MS) s.last24h += 1;
    sourceMap.set(key, s);
  }
  const sources = [...sourceMap.entries()]
    .map(([source, s]) => ({ source, ...s }))
    .sort((a, b) => b.count - a.count || a.source.localeCompare(b.source));

  // --- Companies (corporate + edu domains, grouped) -------------------------
  const domainGroups = new Map<string, { kind: 'corporate' | 'edu'; rows: WaitlistRow[] }>();
  for (const r of real) {
    const domain = domainOf(r.email);
    if (!domain) continue;
    const kind = classifyDomain(domain);
    if (kind === 'personal') continue;
    const g = domainGroups.get(domain) ?? { kind, rows: [] };
    g.rows.push(r);
    domainGroups.set(domain, g);
  }
  const toEntry = (r: WaitlistRow): IntelEntry => ({
    email: r.email,
    source: r.source,
    note: r.note?.trim() || null,
    createdAt: r.createdAt.toISOString(),
  });
  const companies: IntelCompany[] = [...domainGroups.entries()]
    .map(([domain, g]) => ({
      domain,
      kind: g.kind,
      count: g.rows.length,
      knownName: KNOWN_COMPANIES[domain] ?? null,
      latestAt: g.rows[0].createdAt.toISOString(), // rows already newest-first
      entries: g.rows.map(toEntry),
    }))
    // Team clusters first (count desc), then known orgs, then most recent.
    .sort(
      (a, b) =>
        b.count - a.count ||
        Number(Boolean(b.knownName)) - Number(Boolean(a.knownName)) ||
        b.latestAt.localeCompare(a.latestAt)
    );

  // --- Recent feed -----------------------------------------------------------
  const recent: IntelRecent[] = real.slice(0, RECENT_LIMIT).map((r) => {
    const domain = domainOf(r.email);
    return {
      id: r.id,
      ...toEntry(r),
      domainKind: classifyDomain(domain),
      knownName: KNOWN_COMPANIES[domain] ?? null,
    };
  });

  // --- Notes (all messages, newest first) -------------------------------------
  const notes = real.filter(hasNote).map((r) => ({
    ...toEntry(r),
    knownName: KNOWN_COMPANIES[domainOf(r.email)] ?? null,
  }));

  return {
    generatedAt: new Date(now).toISOString(),
    totals: {
      all: real.length,
      lastHour: inWindow(HOUR_MS),
      last24h: inWindow(DAY_MS),
      last7d: inWindow(7 * DAY_MS),
      withNotes: notes.length,
      corporate: corporateCount,
      corporatePct: real.length ? Math.round((corporateCount / real.length) * 100) : 0,
    },
    trend,
    sources,
    companies,
    recent,
    notes,
  };
}

/**
 * Admin authorization
 *
 * There is no role system — admin access is an email allowlist checked
 * server-side at every surface (middleware, page, and API handler). The list
 * is not a secret, it's an authorization rule; the ADMIN_EMAILS env var adds
 * more admins (unioned with the default so the owner can never be locked
 * out; takes effect on the next deploy).
 */

const DEFAULT_ADMINS = 'thedotmack@gmail.com';

const ADMIN_EMAILS = new Set(
  `${DEFAULT_ADMINS},${process.env.ADMIN_EMAILS ?? ''}`
    .split(',')
    .map((e) => e.trim().toLowerCase())
    .filter(Boolean)
);

export function isAdminUser(
  user: { email?: string | null } | null | undefined
): boolean {
  const email = user?.email?.toLowerCase();
  return Boolean(email && ADMIN_EMAILS.has(email));
}

/**
 * GET /api/admin/waitlist
 *
 * Admin-only waitlist intelligence payload for the /admin dashboard.
 * Auth: Supabase session + email allowlist (isAdminUser), enforced both here
 * and in middleware (edge JSON 404 for unauthenticated /api/admin/*). 404 is
 * used over 401/403 to give probers as little as possible.
 */

import { NextResponse } from 'next/server';
import { desc } from 'drizzle-orm';
import { db, emailWaitlist } from '@/db';
import { getUser } from '@/lib/auth-server';
import { isAdminUser } from '@/lib/admin/auth';
import { buildWaitlistIntel } from '@/lib/admin/waitlist-intel';

export const dynamic = 'force-dynamic';

// Sanity cap so the payload can't grow unbounded; revisit with pagination
// long before the waitlist hits this.
const MAX_ROWS = 20_000;

export async function GET() {
  const user = await getUser();

  if (!isAdminUser(user)) {
    return NextResponse.json({ error: 'Not found' }, { status: 404 });
  }

  try {
    const rows = await db
      .select({
        id: emailWaitlist.id,
        email: emailWaitlist.email,
        source: emailWaitlist.source,
        note: emailWaitlist.note,
        createdAt: emailWaitlist.createdAt,
      })
      .from(emailWaitlist)
      .orderBy(desc(emailWaitlist.createdAt))
      .limit(MAX_ROWS);

    const intel = buildWaitlistIntel(rows);
    return NextResponse.json(intel, {
      headers: { 'Cache-Control': 'no-store' },
    });
  } catch (error) {
    console.error('[admin/waitlist] error:', error);
    return NextResponse.json({ error: 'Something went wrong' }, { status: 500 });
  }
}

