  'novibet.com': 'Novibet',
  'truecommerce.com': 'TrueCommerce',
  'myalfred.com': 'myAlfred (UAE super-app)',
  'chilipiper.com': 'Chili Piper',
  'aldar.com': 'Aldar Properties',
  'buk.cl': 'Buk',
  'aunalytics.com': 'Aunalytics',
  '3yourmind.com': '3YOURMIND',
  'kickdrumtech.com': 'Kickdrum',
  'dhc.com.cn': 'DHC Software',
  'wejungle.com': 'Jungle',
};

/** Academic domains: .edu, or .edu.xx / .ac.xx ccTLD second-levels. */
const EDU_RE = /\.edu$|\.(edu|ac)\.[a-z]{2}$/;

export function classifyDomain(domain: string): DomainKind {
  if (!domain) return 'personal'; // malformed email — a person, not an org
  if (FREE_PROVIDERS.has(domain) || TYPO_PROVIDERS.has(domain)) return 'personal';
  if (EDU_RE.test(domain)) return 'edu';
  return 'corporate';
