const HOUR_MS = 3_600_000;
const DAY_MS = 86_400_000;
const TREND_HOURS = 48;
const RECENT_LIMIT = 100;

export function buildWaitlistIntel(rows: WaitlistRow[]): WaitlistIntel {
  const now = Date.now();

  // Drop placeholder/test rows entirely.
  const real = rows.filter((r) => !r.email.toLowerCase().endsWith('@example.com'));
  // Newest first everywhere.
  real.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());

  const domainOf = (email: string) => (email.split('@')[1] ?? '').toLowerCase().trim();
  const hasNote = (r: WaitlistRow) => Boolean(r.note && r.note.trim());

  // --- Totals -------------------------------------------------------------
  const inWindow = (ms: number) => real.filter((r) => now - r.createdAt.getTime() < ms).length;
  let corporateCount = 0;
  for (const r of real) {
    if (classifyDomain(domainOf(r.email)) === 'corporate') corporateCount += 1;
  }

  // --- Hourly trend (last 48h, aligned to hour starts) ---------------------
  const trendStart = Math.floor(now / HOUR_MS) * HOUR_MS - (TREND_HOURS - 1) * HOUR_MS;
  const buckets = new Array<number>(TREND_HOURS).fill(0);
  for (const r of real) {
    const idx = Math.floor((r.createdAt.getTime() - trendStart) / HOUR_MS);
    if (idx >= 0 && idx < TREND_HOURS) buckets[idx] += 1;
  }
  const trend = buckets.map((count, i) => ({
    hourStart: new Date(trendStart + i * HOUR_MS).toISOString(),
    count,
  }));

  // --- Sources --------------------------------------------------------------
  const sourceMap = new Map<string, { count: number; last24h: number }>();
  for (const r of real) {
    const key = r.source?.trim() || '(none)';
    const s = sourceMap.get(key) ?? { count: 0, last24h: 0 };
    s.count += 1;
    if (now - r.createdAt.getTime() < DAY_MS) s.last24h += 1;
    sourceMap.set(key, s);
  }
  const sources = [...sourceMap.entries()]
    .map(([source, s]) => ({ source, ...s }))
    .sort((a, b) => b.count - a.count || a.source.localeCompare(b.source));

  // --- Companies (corporate + edu domains, grouped) -------------------------
  const domainGroups = new Map<string, { kind: 'corporate' | 'edu'; rows: WaitlistRow[] }>();
  for (const r of real) {
    const domain = domainOf(r.email);
    if (!domain) continue;
    const kind = classifyDomain(domain);
    if (kind === 'personal') continue;
    const g = domainGroups.get(domain) ?? { kind, rows: [] };
    g.rows.push(r);
    domainGroups.set(domain, g);
  }
  const toEntry = (r: WaitlistRow): IntelEntry => ({
    email: r.email,
    source: r.source,
    note: r.note?.trim() || null,
    createdAt: r.createdAt.toISOString(),
  });
  const companies: IntelCompany[] = [...domainGroups.entries()]
    .map(([domain, g]) => ({
      domain,
      kind: g.kind,
      count: g.rows.length,
      knownName: KNOWN_COMPANIES[domain] ?? null,
      latestAt: g.rows[0].createdAt.toISOString(), // rows already newest-first
      entries: g.rows.map(toEntry),
    }))
    // Team clusters first (count desc), then known orgs, then most recent.
    .sort(
      (a, b) =>
        b.count - a.count ||
        Number(Boolean(b.knownName)) - Number(Boolean(a.knownName)) ||
        b.latestAt.localeCompare(a.latestAt)
    );

  // --- Recent feed -----------------------------------------------------------
  const recent: IntelRecent[] = real.slice(0, RECENT_LIMIT).map((r) => {
    const domain = domainOf(r.email);
    return {
      id: r.id,
      ...toEntry(r),
      domainKind: classifyDomain(domain),
      knownName: KNOWN_COMPANIES[domain] ?? null,
    };
  });

  // --- Notes (all messages, newest first) -------------------------------------
  const notes = real.filter(hasNote).map((r) => ({
    ...toEntry(r),
    knownName: KNOWN_COMPANIES[domainOf(r.email)] ?? null,
  }));

  return {
    generatedAt: new Date(now).toISOString(),
    totals: {
      all: real.length,
      lastHour: inWindow(HOUR_MS),
      last24h: inWindow(DAY_MS),
      last7d: inWindow(7 * DAY_MS),
      withNotes: notes.length,
      corporate: corporateCount,
      corporatePct: real.length ? Math.round((corporateCount / real.length) * 100) : 0,
    },
    trend,
    sources,
    companies,
    recent,
    notes,
  };
}

