/**
 * Lead report builder
 *
 * Pure aggregation over email_waitlist rows → one JSON payload the /admin
 * "Lead report" panel renders. No DB access here so the logic is
 * unit-testable; the API route fetches rows and calls buildLeadReport().
 *
 * Three questions this answers, in order:
 *   1. What KINDS of leads are on the waitlist? (segments — reuses the
 *      corporate/edu/personal + team-cluster/known-company classification
 *      already built for waitlist-intel.ts)
 *   2. What do their messages REVEAL about why they want this? (themes —
 *      keyword-tagged over the free-text `note` field)
 *   3. Which leads are the BEST ones to act on? (score — a transparent,
 *      additive point system with a human-readable reason per point source,
 *      not a black box)
 */

import { type WaitlistRow, type DomainKind, classifyDomain, KNOWN_COMPANIES } from './waitlist-intel';

export type LeadSegmentKey =
  | 'team-cluster'
  | 'known-company'
  | 'corporate-solo'
  | 'academic'
  | 'individual';

export interface LeadSegment {
  key: LeadSegmentKey;
  label: string;
  description: string;
  count: number;
  pct: number;
  withMessageCount: number;
  withMessagePct: number;
}

export interface ThemeExample {
  email: string;
  domain: string;
  knownName: string | null;
  quote: string;
  createdAt: string;
}

export interface LeadTheme {
  key: string;
  label: string;
  count: number;
  examples: ThemeExample[];
}

export interface ScoredLead {
  email: string;
  domain: string;
  domainKind: DomainKind;
  knownName: string | null;
  segment: LeadSegmentKey;
  source: string | null;
  note: string | null;
  createdAt: string;
  clusterSize: number;
  score: number;
  reasons: string[];
}

export interface LeadMessage {
  email: string;
  domain: string;
  knownName: string | null;
  source: string | null;
  note: string;
  createdAt: string;
}

export interface LeadReport {
  generatedAt: string;
  totals: {
    all: number;
    withMessages: number;
    withMessagesPct: number;
    corporatePct: number;
    teamClusterDomains: number;
  };
  narrative: {
    overview: string;
    typeSummary: string;
    revealSummary: string;
    bestLeadsSummary: string;
  };
  segments: LeadSegment[];
  themes: LeadTheme[];
  bestLeads: ScoredLead[];
  messages: LeadMessage[];
}

const SEGMENT_DEFS: Record<LeadSegmentKey, { label: string; description: string }> = {
  'team-cluster': {
    label: 'Team clusters',
    description:
      '2+ people from the same company domain — the strongest signal we have that a whole team, not just one curious engineer, wants this.',
  },
  'known-company': {
    label: 'Known companies',
    description:
      'A signup from a company we have manually identified by name — a named brand is evaluating the product, even if only one person so far.',
  },
  'corporate-solo': {
    label: 'Corporate (solo)',
    description:
      'One person signing up from a company domain we have not identified by name — likely an individual engineer scouting on their own or ahead of a team pitch.',
  },
  academic: {
    label: 'Academic',
    description:
      '.edu or equivalent academic domains — students and researchers. Lower near-term commercial intent, but useful validation and word-of-mouth.',
  },
  individual: {
    label: 'Individual / indie',
    description:
      'Personal email providers (Gmail, Outlook, iCloud, etc.) — solo developers and hobbyists. Usually the largest group by volume, and the best source of grassroots product feedback.',
  },
};

const THEME_DEFS: Array<{ key: string; label: string; pattern: RegExp }> = [
  {
    key: 'team-adoption',
    label: 'Team / company adoption',
    pattern: /\b(team|company|org(?:s|anization)?|colleagues?|co-?workers?|department|enterprise)\b/i,
  },
  {
    key: 'ai-agent-workflow',
    label: 'AI coding agent workflow',
    pattern: /\b(claude|cursor|copilot|codex|ai agent|coding assistant|\bllm\b|agentic)\b/i,
  },
  {
    key: 'memory-context',
    label: 'Memory / context continuity',
    pattern: /\b(memory|context|remember(?:ing|s)?|forgets?|forgetting|history|continuity|session)\b/i,
  },
  {
    key: 'repetition-pain',
    label: 'Pain point: repeating themselves',
    pattern: /\b(repeat(?:ing)?|re-?explain(?:ing)?|lose context|losing context|start(?:ing)? over|from scratch)\b/i,
  },
  {
    key: 'competitor-mention',
    label: 'Competitor / alternative mentioned',
    pattern: /\b(mem0|langchain|pinecone|chroma|weaviate|zep|letta|vector ?db|vector database|\brag\b)\b/i,
  },
  {
    key: 'engineering-use-case',
    label: 'Engineering / codebase use case',
    pattern: /\b(developers?|engineers?|engineering|codebase|repo(?:sitory)?|software|build(?:ing)?|dev team)\b/i,
  },
  {
    key: 'solo-project',
    label: 'Solo / side project',
    pattern: /\b(solo|myself|personal project|side project|hobby|indie)\b/i,
  },
  {
    key: 'pricing-interest',
    label: 'Pricing / plan interest',
    pattern: /\b(price|pricing|plans?|cost|budget|seats?|enterprise plan)\b/i,
  },
];

const DAY_MS = 86_400_000;
const RECENT_WINDOW_MS = 7 * DAY_MS;
const RECENT_MID_WINDOW_MS = 30 * DAY_MS;
const CLUSTER_BONUS_CAP = 5;
const BEST_LEADS_LIMIT = 30;
const QUOTE_MAX_LEN = 160;

function domainOf(email: string): string {
  return (email.split('@')[1] ?? '').toLowerCase().trim();
}

function truncate(text: string, max: number): string {
  const trimmed = text.trim();
  return trimmed.length > max ? `${trimmed.slice(0, max - 1)}…` : trimmed;
}

function classifySegment(
  domainKind: DomainKind,
  knownName: string | null,
  clusterSize: number
): LeadSegmentKey {
  if (domainKind === 'corporate' && clusterSize >= 2) return 'team-cluster';
  if (domainKind === 'corporate' && knownName) return 'known-company';
  if (domainKind === 'corporate') return 'corporate-solo';
  if (domainKind === 'edu') return 'academic';
  return 'individual';
}

function scoreLead(
  row: WaitlistRow,
  domainKind: DomainKind,
  knownName: string | null,
  clusterSize: number,
  now: number
): { score: number; reasons: string[] } {
  let score = 0;
  const reasons: string[] = [];
  const note = row.note?.trim() || '';
  const domain = domainOf(row.email);

  if (domainKind === 'corporate') {
    score += 35;
    reasons.push(`Corporate domain (${domain})`);
  } else if (domainKind === 'edu') {
    score += 10;
    reasons.push(`Academic domain (${domain})`);
  }

  if (knownName) {
    score += 15;
    reasons.push(`Known company: ${knownName}`);
  }

  if (clusterSize >= 2) {
    const bonus = Math.min(clusterSize - 1, CLUSTER_BONUS_CAP) * 8;
    score += bonus;
    reasons.push(`Part of a ${clusterSize}-person team cluster (+${bonus})`);
  }

  if (note) {
    score += 20;
    reasons.push("Left a message about what they're working on");
    if (note.length > 60) {
      score += 10;
      reasons.push('Message is detailed (60+ characters)');
    }
  }

  const age = now - row.createdAt.getTime();
  if (age < RECENT_WINDOW_MS) {
    score += 12;
    reasons.push('Signed up in the last 7 days — still fresh');
  } else if (age < RECENT_MID_WINDOW_MS) {
    score += 6;
    reasons.push('Signed up in the last 30 days');
  }

  return { score, reasons };
}

function buildNarrative(
  totals: LeadReport['totals'],
  segments: LeadSegment[],
  themes: LeadTheme[],
  bestLeads: ScoredLead[]
): LeadReport['narrative'] {
  const overview = totals.all
    ? `${totals.all} people have joined the waitlist so far. ${totals.withMessages} of them (${totals.withMessagesPct}%) left a message about what they're working on, and ${totals.corporatePct}% are signing up from a company or school domain rather than a personal inbox.`
    : 'No waitlist signups yet.';

  const topSegments = [...segments].filter((s) => s.count > 0).sort((a, b) => b.count - a.count).slice(0, 3);
  const typeSummary = topSegments.length
    ? `The largest group is ${topSegments[0].label} (${topSegments[0].count} people, ${topSegments[0].pct}%)` +
      (topSegments[1] ? `, followed by ${topSegments[1].label} (${topSegments[1].count}, ${topSegments[1].pct}%)` : '') +
      (topSegments[2] ? ` and ${topSegments[2].label} (${topSegments[2].count}, ${topSegments[2].pct}%)` : '') +
      '.'
    : 'Not enough data yet to break down lead types.';

  const topThemes = themes.slice(0, 3);
  const revealSummary = topThemes.length
    ? `Across the messages people left, the most common thread is "${topThemes[0].label}" (${topThemes[0].count} mention${topThemes[0].count === 1 ? '' : 's'})` +
      (topThemes[1] ? `, followed by "${topThemes[1].label}" (${topThemes[1].count})` : '') +
      (topThemes[2] ? ` and "${topThemes[2].label}" (${topThemes[2].count})` : '') +
      ' — a read on why people actually want this, in their own words.'
    : 'No messages yet to analyze for themes.';

  const strongCount = bestLeads.filter((l) => l.score >= 60).length;
  const bestLeadsSummary = bestLeads.length
    ? `${bestLeads[0].knownName ?? bestLeads[0].domain} leads the ranking at a score of ${bestLeads[0].score}. ${strongCount} lead${strongCount === 1 ? '' : 's'} score 60+, combining an organizational signal (corporate or team) with an engaged message and recent signup — those are worth reaching out to directly.`
    : 'No leads have scored high enough yet to highlight.';

  return { overview, typeSummary, revealSummary, bestLeadsSummary };
}

export function buildLeadReport(rows: WaitlistRow[]): LeadReport {
  const now = Date.now();

  // Drop placeholder/test rows entirely, same rule as waitlist-intel.
  const real = rows.filter((r) => !r.email.toLowerCase().endsWith('@example.com'));
  real.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());

  // --- Cluster sizes per corporate/edu domain (drives segment + score) -----
  const clusterSizes = new Map<string, number>();
  for (const r of real) {
    const domain = domainOf(r.email);
    if (!domain || classifyDomain(domain) === 'personal') continue;
    clusterSizes.set(domain, (clusterSizes.get(domain) ?? 0) + 1);
  }

  // --- Per-row classification, shared across segments/scoring/messages -----
  type Classified = {
    row: WaitlistRow;
    domain: string;
    domainKind: DomainKind;
    knownName: string | null;
    clusterSize: number;
    segment: LeadSegmentKey;
  };
  const classified: Classified[] = real.map((row) => {
    const domain = domainOf(row.email);
    const domainKind = classifyDomain(domain);
    const knownName = KNOWN_COMPANIES[domain] ?? null;
    const clusterSize = domainKind === 'personal' ? 1 : (clusterSizes.get(domain) ?? 1);
    const segment = classifySegment(domainKind, knownName, clusterSize);
    return { row, domain, domainKind, knownName, clusterSize, segment };
  });

  // --- Segments ("types of leads") ------------------------------------------
  const segmentAgg = new Map<LeadSegmentKey, { count: number; withMessage: number }>();
  for (const c of classified) {
    const agg = segmentAgg.get(c.segment) ?? { count: 0, withMessage: 0 };
    agg.count += 1;
    if (c.row.note?.trim()) agg.withMessage += 1;
    segmentAgg.set(c.segment, agg);
  }
  const segments: LeadSegment[] = (Object.keys(SEGMENT_DEFS) as LeadSegmentKey[]).map((key) => {
    const agg = segmentAgg.get(key) ?? { count: 0, withMessage: 0 };
    return {
      key,
      label: SEGMENT_DEFS[key].label,
      description: SEGMENT_DEFS[key].description,
      count: agg.count,
      pct: real.length ? Math.round((agg.count / real.length) * 100) : 0,
      withMessageCount: agg.withMessage,
      withMessagePct: agg.count ? Math.round((agg.withMessage / agg.count) * 100) : 0,
    };
  });

  // --- Themes ("what is revealed") -------------------------------------------
  const themeAgg = new Map<string, ThemeExample[]>();
  for (const c of classified) {
    const note = c.row.note?.trim();
    if (!note) continue;
    for (const def of THEME_DEFS) {
      if (!def.pattern.test(note)) continue;
      const examples = themeAgg.get(def.key) ?? [];
      if (examples.length < 3) {
        examples.push({
          email: c.row.email,
          domain: c.domain,
          knownName: c.knownName,
          quote: truncate(note, QUOTE_MAX_LEN),
          createdAt: c.row.createdAt.toISOString(),
        });
      }
      themeAgg.set(def.key, examples);
    }
  }
  const themeCounts = new Map<string, number>();
  for (const c of classified) {
    const note = c.row.note?.trim();
    if (!note) continue;
    for (const def of THEME_DEFS) {
      if (def.pattern.test(note)) themeCounts.set(def.key, (themeCounts.get(def.key) ?? 0) + 1);
    }
  }
  const themes: LeadTheme[] = THEME_DEFS.map((def) => ({
    key: def.key,
    label: def.label,
    count: themeCounts.get(def.key) ?? 0,
    examples: themeAgg.get(def.key) ?? [],
  }))
    .filter((t) => t.count > 0)
    .sort((a, b) => b.count - a.count);

  // --- Best leads (scored, ranked) ---------------------------------------
  const bestLeads: ScoredLead[] = classified
    .map((c) => {
      const { score, reasons } = scoreLead(c.row, c.domainKind, c.knownName, c.clusterSize, now);
      return {
        email: c.row.email,
        domain: c.domain,
        domainKind: c.domainKind,
        knownName: c.knownName,
        segment: c.segment,
        source: c.row.source,
        note: c.row.note?.trim() || null,
        createdAt: c.row.createdAt.toISOString(),
        clusterSize: c.clusterSize,
        score,
        reasons,
      };
    })
    .sort((a, b) => b.score - a.score || b.createdAt.localeCompare(a.createdAt))
    .slice(0, BEST_LEADS_LIMIT);

  // --- All messages ("get all the messages data from the leads") -----------
  const messages: LeadMessage[] = classified
    .filter((c) => c.row.note?.trim())
    .map((c) => ({
      email: c.row.email,
      domain: c.domain,
      knownName: c.knownName,
      source: c.row.source,
      note: c.row.note!.trim(),
      createdAt: c.row.createdAt.toISOString(),
    }));

  const totals: LeadReport['totals'] = {
    all: real.length,
    withMessages: messages.length,
    withMessagesPct: real.length ? Math.round((messages.length / real.length) * 100) : 0,
    corporatePct: real.length
      ? Math.round((classified.filter((c) => c.domainKind === 'corporate').length / real.length) * 100)
      : 0,
    teamClusterDomains: [...clusterSizes.values()].filter((n) => n >= 2).length,
  };

  return {
    generatedAt: new Date(now).toISOString(),
    totals,
    narrative: buildNarrative(totals, segments, themes, bestLeads),
    segments,
    themes,
    bestLeads,
    messages,
  };
}

