/**
 * GET /api/admin/leads-report
 *
 * Admin-only lead intelligence payload for the /admin "Lead report" panel:
 * lead type breakdown, message themes, and a scored best-leads ranking.
 * Auth: Supabase session + email allowlist (isAdminUser), enforced both here
 * and in middleware (edge JSON 404 for unauthenticated /api/admin/*). 404 is
 * used over 401/403 to give probers as little as possible.
 */

import { NextResponse } from 'next/server';
import { desc } from 'drizzle-orm';
import { db, emailWaitlist } from '@/db';
import { getUser } from '@/lib/auth-server';
import { isAdminUser } from '@/lib/admin/auth';
import { buildLeadReport } from '@/lib/admin/lead-report';

export const dynamic = 'force-dynamic';

// Sanity cap so the payload can't grow unbounded; revisit with pagination
// long before the waitlist hits this.
const MAX_ROWS = 20_000;

export async function GET() {
  const user = await getUser();

  if (!isAdminUser(user)) {
    return NextResponse.json({ error: 'Not found' }, { status: 404 });
  }

  try {
    const rows = await db
      .select({
        id: emailWaitlist.id,
        email: emailWaitlist.email,
        source: emailWaitlist.source,
        note: emailWaitlist.note,
        createdAt: emailWaitlist.createdAt,
      })
      .from(emailWaitlist)
      .orderBy(desc(emailWaitlist.createdAt))
      .limit(MAX_ROWS);

    const report = buildLeadReport(rows);
    return NextResponse.json(report, {
      headers: { 'Cache-Control': 'no-store' },
    });
  } catch (error) {
    console.error('[admin/leads-report] error:', error);
    return NextResponse.json({ error: 'Something went wrong' }, { status: 500 });
  }
}

