import { NextResponse, type NextRequest } from "next/server";
import { updateSession } from "@/lib/supabase/middleware";

export async function middleware(request: NextRequest) {
  // imprint.cmem.ai is served from the /imprint route. Rewrite the host's
  // requests onto that segment so the subdomain shows the imprint page at its
  // own root (and still reachable at cmem.ai/imprint for local testing).
  const host = (request.headers.get("host") || "").split(":")[0];
  if (host === "imprint.cmem.ai" || host.startsWith("imprint.localhost")) {
    const url = request.nextUrl.clone();
    if (!url.pathname.startsWith("/imprint")) {
      url.pathname = `/imprint${url.pathname === "/" ? "" : url.pathname}`;
      return NextResponse.rewrite(url);
    }
    return NextResponse.next();
  }

  return await updateSession(request);
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     * - public files (images, etc.)
     * - api/mcp (remote MCP server — bearer-auth only, must not run the
     *   Supabase session/redirect middleware which would interfere with the
     *   Streamable-HTTP MCP handshake and its WWW-Authenticate flow)
     * - api/pro/sync (worker sync lanes — bearer setup-token + X-User-Id, no
     *   cookies; the Supabase session middleware would burn a GoTrue round
     *   trip per push that can never succeed. Other /api/pro/* routes use
     *   cookie auth and MUST stay matched.)
     */
    "/((?!_next/static|_next/image|favicon.ico|api/mcp|api/pro/sync|.*\\.svg$|.*\\.png$|.*\\.jpg$|.*\\.jpeg$|.*\\.gif$|.*\\.webp$|assets/).*)",
  ],
};

