'use client';

/**
 * Lead report (client side of /admin's "Lead report" tab).
 *
 * Answers three questions over email_waitlist: what kinds of leads are on
 * the list (segments), what their messages reveal (themes), and which are
 * the best ones to act on (scored ranking) — plus the full raw message log.
 * Polls /api/admin/leads-report every 30s (paused while the tab is hidden).
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import type { LeadReport as LeadReportData, LeadTheme, ScoredLead, LeadMessage } from '@/lib/admin/lead-report';

const POLL_MS = 30_000;

function ago(iso: string): string {
  const s = (Date.now() - new Date(iso).getTime()) / 1000;
  if (s < 60) return `${Math.max(0, Math.floor(s))}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

function stamp(iso: string): string {
  return new Date(iso).toLocaleString(undefined, {
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

function StatCard({ label, value, accent }: { label: string; value: string | number; accent?: boolean }) {
  return (
    <div className={`aw-stat${accent ? ' aw-stat-accent' : ''}`}>
      <div className="aw-stat-value">{value}</div>
      <div className="aw-stat-label">{label}</div>
    </div>
  );
}

function SegmentBars({ segments }: { segments: LeadReportData['segments'] }) {
  const max = Math.max(1, ...segments.map((s) => s.count));
  return (
    <div className="aw-sources">
      {segments.map((s) => (
        <details key={s.key} className="lr-segment">
          <summary
            className="aw-source-row lr-segment-summary"
            title={`${s.count} total · ${s.withMessagePct}% left a message`}
          >
            <span className="aw-source-name">{s.label}</span>
            <span className="aw-source-track">
              <span className="aw-source-fill" style={{ width: `${(s.count / max) * 100}%` }} />
            </span>
            <span className="aw-source-count">
              {s.count} <em className="aw-source-delta">{s.pct}%</em>
            </span>
          </summary>
          <p className="lr-segment-desc">{s.description}</p>
        </details>
      ))}
      {segments.every((s) => s.count === 0) && <div className="aw-empty">No signups yet.</div>}
    </div>
  );
}

function ThemeCard({ theme }: { theme: LeadTheme }) {
  return (
    <details className="aw-company" open={theme.count >= 3}>
      <summary className="aw-company-summary">
        <span className="aw-company-domain">{theme.label}</span>
        <span className="aw-badge aw-badge-cluster">{theme.count}</span>
      </summary>
      <div className="aw-company-entries">
        {theme.examples.map((e) => (
          <div key={`${e.email}-${e.createdAt}`} className="aw-entry">
            <div className="aw-entry-head">
              <span className="aw-entry-email">{e.email}</span>
              {e.knownName && <span className="aw-badge aw-badge-known">{e.knownName}</span>}
              <span className="aw-entry-when" title={stamp(e.createdAt)}>{ago(e.createdAt)}</span>
            </div>
            <div className="aw-note">“{e.quote}”</div>
          </div>
        ))}
      </div>
    </details>
  );
}

function BestLeadRow({ lead, rank }: { lead: ScoredLead; rank: number }) {
  return (
    <div className="lr-lead">
      <div className="lr-lead-head">
        <span className="lr-lead-rank">#{rank}</span>
        <span className="aw-entry-email">{lead.email}</span>
        {lead.knownName && <span className="aw-badge aw-badge-known">{lead.knownName}</span>}
        {lead.domainKind === 'corporate' && !lead.knownName && <span className="aw-badge aw-badge-corp">corp</span>}
        {lead.domainKind === 'edu' && <span className="aw-badge aw-badge-edu">edu</span>}
        {lead.clusterSize >= 2 && <span className="aw-badge aw-badge-cluster">×{lead.clusterSize}</span>}
        <span className="lr-lead-score">{lead.score}</span>
      </div>
      <div className="lr-lead-reasons">
        {lead.reasons.map((r) => (
          <span key={r} className="aw-chip">{r}</span>
        ))}
      </div>
      {lead.note && <div className="aw-note">“{lead.note}”</div>}
      <div className="aw-entry-when lr-lead-when" title={stamp(lead.createdAt)}>{ago(lead.createdAt)}</div>
    </div>
  );
}

function MessageRow({ msg }: { msg: LeadMessage }) {
  return (
    <div className="aw-feed-row">
      <div className="aw-entry-head">
        <span className="aw-entry-email">{msg.email}</span>
        {msg.knownName && <span className="aw-badge aw-badge-known">{msg.knownName}</span>}
        <span className="aw-chip">{msg.source ?? '?'}</span>
        <span className="aw-entry-when" title={stamp(msg.createdAt)}>{ago(msg.createdAt)}</span>
      </div>
      <div className="aw-note">“{msg.note}”</div>
    </div>
  );
}

export default function LeadReport({ embedded = false }: { embedded?: boolean }) {
  const [data, setData] = useState<LeadReportData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [lastFetched, setLastFetched] = useState<number | null>(null);
  const [tab, setTab] = useState<'best' | 'messages'>('best');
  const reqSeq = useRef(0);

  const load = useCallback(async () => {
    const seq = ++reqSeq.current;
    try {
      const res = await fetch('/api/admin/leads-report', { cache: 'no-store' });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const report: LeadReportData = await res.json();
      if (seq !== reqSeq.current) return;
      setData(report);
      setError(null);
      setLastFetched(Date.now());
    } catch (e) {
      if (seq !== reqSeq.current) return;
      setError(e instanceof Error ? e.message : 'fetch failed');
    }
  }, []);

  useEffect(() => {
    void load();
    const interval = setInterval(() => {
      if (document.visibilityState === 'visible') void load();
    }, POLL_MS);
    const onVisible = () => {
      if (document.visibilityState === 'visible') void load();
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      clearInterval(interval);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [load]);

  if (!data) {
    return (
      <div className={`aw-shell${embedded ? ' aw-shell-embedded' : ''}`}>
        <div className="aw-loading">{error ? `Failed to load: ${error}` : 'Loading lead report…'}</div>
      </div>
    );
  }

  const { totals, narrative, segments, themes, bestLeads, messages } = data;

  return (
    <div className={`aw-shell${embedded ? ' aw-shell-embedded' : ''}`}>
      <header className="aw-header">
        <div className="aw-title-block">
          <h1 className="aw-title">
            <span className="aw-live-dot" aria-hidden />
            Lead report
          </h1>
          <span className="aw-subtitle">
            {error
              ? `refresh failed (${error}) — showing last good data`
              : lastFetched
                ? `updated ${new Date(lastFetched).toLocaleTimeString()} · polls every 30s`
                : ''}
          </span>
        </div>
        <button className="aw-refresh" onClick={() => void load()}>
          Refresh
        </button>
      </header>

      <section className="aw-stats">
        <StatCard label="Total leads" value={totals.all} accent />
        <StatCard label="With messages" value={`${totals.withMessages} (${totals.withMessagesPct}%)`} />
        <StatCard label="Corporate" value={`${totals.corporatePct}%`} />
        <StatCard label="Team-cluster domains" value={totals.teamClusterDomains} />
      </section>

      <section className="aw-panel lr-narrative">
        <h2 className="aw-panel-title">What the data says</h2>
        <p className="lr-narrative-p">{narrative.overview}</p>
        <p className="lr-narrative-p"><strong>Types of leads. </strong>{narrative.typeSummary}</p>
        <p className="lr-narrative-p"><strong>What's revealed. </strong>{narrative.revealSummary}</p>
        <p className="lr-narrative-p"><strong>Best leads. </strong>{narrative.bestLeadsSummary}</p>
      </section>

      <div className="aw-columns">
        <div className="aw-col">
          <section className="aw-panel">
            <h2 className="aw-panel-title">Types of leads</h2>
            <SegmentBars segments={segments} />
          </section>

          <section className="aw-panel">
            <h2 className="aw-panel-title">
              What's revealed <span className="aw-panel-meta">{themes.length} themes in {totals.withMessages} messages</span>
            </h2>
            <div className="aw-company-list">
              {themes.map((t) => (
                <ThemeCard key={t.key} theme={t} />
              ))}
              {themes.length === 0 && <div className="aw-empty">No messages yet to analyze.</div>}
            </div>
          </section>
        </div>

        <div className="aw-col">
          <section className="aw-panel">
            <div className="aw-tabs">
              <button
                className={`aw-tab${tab === 'best' ? ' aw-tab-active' : ''}`}
                aria-pressed={tab === 'best'}
                onClick={() => setTab('best')}
              >
                Best leads <span className="aw-tab-count">{bestLeads.length}</span>
              </button>
              <button
                className={`aw-tab${tab === 'messages' ? ' aw-tab-active' : ''}`}
                aria-pressed={tab === 'messages'}
                onClick={() => setTab('messages')}
              >
                All messages <span className="aw-tab-count">{messages.length}</span>
              </button>
            </div>

            {tab === 'best' ? (
              <div className="aw-feed lr-lead-list">
                {bestLeads.map((lead, i) => (
                  <BestLeadRow key={lead.email} lead={lead} rank={i + 1} />
                ))}
                {bestLeads.length === 0 && <div className="aw-empty">No leads yet.</div>}
              </div>
            ) : (
              <div className="aw-feed">
                {messages.map((m) => (
                  <MessageRow key={`${m.email}-${m.createdAt}`} msg={m} />
                ))}
                {messages.length === 0 && <div className="aw-empty">No messages yet.</div>}
              </div>
            )}
          </section>
        </div>
      </div>
    </div>
  );
}

