import { createClient } from '@/lib/supabase/server';
import { isAdminUser } from '@/lib/admin/auth';
import AdminWaitlist from './AdminWaitlist';
import './admin.css';

export const dynamic = 'force-dynamic';

export const metadata: Metadata = {
  title: 'Waitlist — admin',
  robots: { index: false, follow: false },
};

export default async function AdminPage() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!isAdminUser(user)) notFound();

  return <AdminWaitlist />;
}

// --- main component ----------------------------------------------------------

export default function AdminWaitlist() {
  const [data, setData] = useState<WaitlistIntel | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [lastFetched, setLastFetched] = useState<number | null>(null);
  const [tab, setTab] = useState<'feed' | 'messages'>('feed');
  const [baseline, setBaseline] = useState<number | null>(null);
  // Monotonic request id: only the newest in-flight fetch may commit state,
  // so an older slow response can't overwrite a newer fast one.
  const reqSeq = useRef(0);

  const load = useCallback(async () => {
    const seq = ++reqSeq.current;
    try {
      const res = await fetch('/api/admin/waitlist', { cache: 'no-store' });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const intel: WaitlistIntel = await res.json();
      if (seq !== reqSeq.current) return; // stale response — drop it
      setData(intel);
      setError(null);
      setLastFetched(Date.now());
      setBaseline((b) => b ?? intel.totals.all);
    } catch (e) {
      if (seq !== reqSeq.current) return;
      setError(e instanceof Error ? e.message : 'fetch failed');
    }
  }, []);

  useEffect(() => {
    void load();
    const interval = setInterval(() => {
      if (document.visibilityState === 'visible') void load();
    }, POLL_MS);
    const onVisible = () => {
      if (document.visibilityState === 'visible') void load();
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      clearInterval(interval);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [load]);

  if (!data) {
    return (
      <div className="aw-shell">
        <div className="aw-loading">{error ? `Failed to load: ${error}` : 'Loading waitlist…'}</div>
