'use client';

/**
 * /admin shell — switches between the live waitlist feed and the lead
 * report (types of leads, what their messages reveal, best leads ranked).
 */

import { useState } from 'react';
import AdminWaitlist from './AdminWaitlist';
import LeadReport from './LeadReport';

type Surface = 'waitlist' | 'leads';

export default function AdminDashboard() {
  const [surface, setSurface] = useState<Surface>('waitlist');
  return (
    <div className="aw-shell">
      <nav className="aw-admin-nav" aria-label="Admin sections">
        <button
          className={`aw-admin-nav-btn${surface === 'waitlist' ? ' is-active' : ''}`}
          aria-pressed={surface === 'waitlist'}
          onClick={() => setSurface('waitlist')}
        >
          Waitlist
        </button>
        <button
          className={`aw-admin-nav-btn${surface === 'leads' ? ' is-active' : ''}`}
          aria-pressed={surface === 'leads'}
          onClick={() => setSurface('leads')}
        >
          Lead report
        </button>
      </nav>
      {surface === 'waitlist' ? <AdminWaitlist embedded /> : <LeadReport embedded />}
    </div>
  );
}

